'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import { neonTest } from '../lib/neon-test-client';
import { bootstrapBasicOrganization } from '../lib/neon-basic-control';
import BasicControlAppV1 from './BasicControlAppV1';
import {
  createCompleteAccount,
  createCompleteObligation,
  createCompleteTransfer,
  settleCompleteObligation,
  cancelCompleteObligation,
  reverseCompleteSettlement,
  reverseCompleteTransfer,
  localToday,
  normalizeCompleteError
} from '../lib/neon-complete-control';
import {
  loadCompleteV34Data,
  updateFinanceObligationSafe,
  createInstallmentPlanV2,
  cancelInstallmentRemainingV2,
  createRecurringRuleV2,
  generateRecurringV2,
  stopRecurringRuleV3
} from '../lib/neon-complete-control-v34';
import styles from './CompleteControlAppV36.module.css';

const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));
const dateBR=v=>v?String(v).slice(0,10).split('-').reverse().join('/'):'—';
const ymd=v=>String(v||'').slice(0,10);
const monthNow=()=>localToday().slice(0,7);
const kindLabel=v=>({bank:'Banco',cash:'Caixa',wallet:'Carteira digital',other:'Outra'})[v]||v;
const statusLabel=v=>({open:'Em aberto',partial:'Parcial',settled:'Quitado',cancelled:'Cancelado',overdue:'Vencido',active:'Ativo',reversed:'Estornado'})[v]||v;
const isTransferKind=v=>String(v||'').startsWith('transfer_');
const signed=(direction,amount)=>direction==='in'?Number(amount||0):-Number(amount||0);
const monthEndAfter=(date,months)=>{const [year,month]=ymd(date).slice(0,7).split('-').map(Number);const d=new Date(Date.UTC(year,month-1+Number(months)+1,0));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`};
function monthBounds(month){const [y,m]=String(month).split('-').map(Number);const last=new Date(Date.UTC(y,m,0)).getUTCDate();return{start:`${month}-01`,end:`${month}-${String(last).padStart(2,'0')}`}}

const NAV=[
  {group:'Operação',items:[['overview','Visão geral','home'],['today','Hoje','today']]},
  {group:'Gestão',items:[['competency','Competência','chart'],['accounts','Contas','wallet'],['receivables','A receber','in'],['payables','A pagar','out']]},
  {group:'Planejamento',items:[['cashflow','Fluxo de caixa','cash'],['statement','Extrato','statement'],['installments','Parcelamentos','installment'],['recurring','Recorrências','repeat']]},
  {group:'Auditoria',items:[['history','Histórico','history']]}
];
const TITLES={overview:['Visão geral','A posição financeira da empresa em uma leitura só.'],today:['Hoje','O que exige atenção agora e nos próximos dias.'],accounts:['Contas','Onde o dinheiro efetivamente está.'],receivables:['Contas a receber','Valores que ainda precisam entrar no caixa.'],payables:['Contas a pagar','Compromissos que ainda precisam sair do caixa.'],cashflow:['Fluxo de caixa','Realizado e projetado com saldo acumulado.'],statement:['Extrato por conta','Movimentações e saldo após cada evento.'],installments:['Parcelamentos','Compras e vendas divididas em obrigações reais.'],recurring:['Recorrências','Compromissos mensais que alimentam o financeiro.'],history:['Histórico financeiro','Baixas, transferências, estornos e trilha de auditoria.']};

function Icon({name}){const p={home:<><path d="M3 11 12 3l9 8"/><path d="M5 10v11h14V10"/></>,today:<><path d="M4 5h16v15H4z"/><path d="M8 3v4M16 3v4M4 10h16"/></>,chart:<><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></>,wallet:<><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M16 10h5v4h-5a2 2 0 0 1 0-4Z"/></>,in:<><path d="M12 3v14"/><path d="m7 12 5 5 5-5"/></>,out:<><path d="M12 21V7"/><path d="m7 12 5-5 5 5"/></>,cash:<><path d="M3 7h18v10H3z"/><circle cx="12" cy="12" r="2.4"/></>,statement:<><path d="M5 3h14v18H5z"/><path d="M8 8h8M8 12h8M8 16h5"/></>,installment:<><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M7 10h10M7 14h4"/></>,repeat:<><path d="M17 2l4 4-4 4"/><path d="M3 11V9a3 3 0 0 1 3-3h15"/><path d="m7 22-4-4 4-4"/><path d="M21 13v2a3 3 0 0 1-3 3H3"/></>,history:<><path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v5h5"/><path d="M12 7v5l3 2"/></>,plus:<path d="M12 5v14M5 12h14"/>,transfer:<><path d="M4 7h14"/><path d="m14 3 4 4-4 4"/><path d="M20 17H6"/><path d="m10 13-4 4 4 4"/></>,refresh:<><path d="M20 7h-5V2"/><path d="M20 7a8 8 0 1 0 1 8"/></>,logout:<><path d="M10 17l5-5-5-5"/><path d="M15 12H3"/><path d="M21 19V5a2 2 0 0 0-2-2h-6"/></>,edit:<><path d="m4 20 4-1 11-11-3-3L5 16z"/><path d="m14 6 3 3"/></>,undo:<><path d="m9 7-5 5 5 5"/><path d="M4 12h10a6 6 0 0 1 6 6"/></>,close:<path d="m6 6 12 12M18 6 6 18"/>,back:<path d="m15 18-6-6 6-6"/>};return <svg viewBox="0 0 24 24" className={styles.icon}>{p[name]||p.home}</svg>}

export default function CompleteControlAppV36(){
  const session=neonTest.auth.useSession();
  const user=session.data?.user||null;
  const activeOrganizationId=session.data?.session?.activeOrganizationId||null;
  const [view,setView]=useState('overview');
  const [data,setData]=useState(null);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState('');
  const [toast,setToast]=useState('');
  const [modal,setModal]=useState(null);
  const [detail,setDetail]=useState(null);
  const [bootstrapped,setBootstrapped]=useState(false);

  const refresh=useCallback(async()=>{if(!user)return;setError('');try{const next=await loadCompleteV34Data(activeOrganizationId);if(next.reload){window.location.reload();return}setData(next)}catch(e){setError(normalizeCompleteError(e))}},[user?.id,activeOrganizationId]);
  useEffect(()=>{if(session.isPending)return;if(!user){setData(null);return}refresh()},[session.isPending,user?.id,refresh]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3200);return()=>clearTimeout(t)},[toast]);

  const company=data?.companies?.[0]||null;
  useEffect(()=>{if(!company||bootstrapped)return;let off=false;(async()=>{try{await bootstrapBasicOrganization(company.id);if(!off){setBootstrapped(true);await refresh()}}catch(e){if(!off)setError(normalizeCompleteError(e))}})();return()=>{off=true}},[company?.id,bootstrapped,refresh]);

  const companyMovements=useMemo(()=>data?.movements.filter(x=>x.companyId===company?.id)||[],[data,company?.id]);
  const accounts=useMemo(()=>{const today=localToday();return(data?.accounts.filter(x=>x.companyId===company?.id)||[]).map(account=>{const opening=ymd(account.openingDate)<=today?Number(account.openingBalance||0):0;const movementBalance=companyMovements.filter(m=>m.accountId===account.id&&ymd(m.date)<=today).reduce((s,m)=>s+signed(m.direction,m.amount),0);return{...account,balance:opening+movementBalance}})},[data,company?.id,companyMovements]);
  const obligations=useMemo(()=>data?.obligations.filter(x=>x.companyId===company?.id)||[],[data,company?.id]);
  const entries=useMemo(()=>data?.entries.filter(x=>x.companyId===company?.id)||[],[data,company?.id]);
  const customers=useMemo(()=>data?.customers.filter(x=>x.organization_id===company?.id&&x.active&&!x.merged_into)||[],[data,company?.id]);
  const suppliers=useMemo(()=>data?.suppliers.filter(x=>x.organization_id===company?.id&&x.active&&!x.merged_into)||[],[data,company?.id]);
  const categories=useMemo(()=>data?.categories.filter(x=>x.organization_id===company?.id&&x.active)||[],[data,company?.id]);
  const linkableEntries=useMemo(()=>entries.map(entry=>{const allocated=obligations.filter(o=>o.financialEntryId===entry.id).reduce((s,o)=>s+(o.status==='cancelled'?o.settledAmount:o.originalAmount),0);return{...entry,allocationRemaining:Math.max(0,entry.amount-allocated)}}).filter(x=>x.allocationRemaining>.00001),[entries,obligations]);

  async function run(fn,message,{keepDetail=false}={}){setBusy(true);setError('');try{await fn();const next=await loadCompleteV34Data(activeOrganizationId);setData(next);setModal(null);if(!keepDetail)setDetail(null);setToast(message)}catch(e){const m=normalizeCompleteError(e);setError(m);setToast(m)}finally{setBusy(false)}}
  async function signOut(){setBusy(true);try{await neonTest.auth.signOut()}finally{window.location.reload()}}

  if(session.isPending||!data)return <Center text="Carregando Controle Completo…"/>;
  if(!company)return <Center text="Nenhuma empresa disponível para este acesso."/>;
  if(view==='competency')return <div className={styles.competencyBridge}><BasicControlAppV1/><button className={styles.backFinance} onClick={()=>{setView('overview');refresh()}}><Icon name="back"/>Voltar ao financeiro</button></div>;

  const title=TITLES[view]||TITLES.overview;
  return <div className={styles.shell}>
    <aside className={styles.sidebar}>
      <div className={styles.brand}><span>LG</span><div><strong>Central Financeira</strong><small>Controle Completo</small></div></div>
      <nav>{NAV.map(group=><section key={group.group}><small>{group.group}</small>{group.items.map(([key,label,icon])=><button key={key} className={view===key?styles.navActive:''} onClick={()=>{setView(key);setDetail(null);setModal(null)}}><Icon name={icon}/><span>{label}</span></button>)}</section>)}</nav>
      <footer><div><small>Empresa</small><strong>{company.name}</strong></div><button onClick={signOut} disabled={busy}><Icon name="logout"/>Sair</button></footer>
    </aside>
    <main className={styles.main}>
      <header className={styles.topbar}><div><span>Controle Completo</span><h1>{title[0]}</h1><p>{title[1]}</p></div><div className={styles.topActions}><HeaderActions view={view} onModal={setModal}/><button className={styles.iconButton} onClick={refresh} disabled={busy} title="Atualizar"><Icon name="refresh"/></button></div></header>
      {error&&<div className={styles.error}>{error}</div>}
      <div className={styles.content}>
        {view==='overview'&&<Overview accounts={accounts} obligations={obligations} onView={setView} onDetail={setDetail}/>} 
        {view==='today'&&<Today accounts={accounts} obligations={obligations} onDetail={setDetail}/>} 
        {view==='accounts'&&<Accounts accounts={accounts}/>} 
        {(view==='receivables'||view==='payables')&&<ObligationsView items={obligations.filter(x=>x.direction===(view==='receivables'?'receivable':'payable'))} onDetail={setDetail} onSettle={o=>setModal({type:'settle',obligation:o})} onCancel={o=>setModal({type:'cancel-obligation',obligation:o})}/>} 
        {view==='cashflow'&&<CashFlow accounts={accounts} obligations={obligations} movements={companyMovements}/>} 
        {view==='statement'&&<Statement accounts={accounts} movements={companyMovements}/>} 
        {view==='installments'&&<Installments data={data} obligations={obligations} companyId={company.id} onDetail={setDetail} onModal={setModal}/>} 
        {view==='recurring'&&<Recurring data={data} obligations={obligations} companyId={company.id} busy={busy} onDetail={setDetail} onModal={setModal} onRun={run}/>} 
        {view==='history'&&<History data={data} companyId={company.id} onReverse={target=>setModal({type:'reverse',target})}/>} 
      </div>
    </main>

    {detail&&<ObligationDrawer obligation={detail} data={data} onClose={()=>setDetail(null)} onEdit={()=>setModal({type:'edit',obligation:detail})} onSettle={()=>setModal({type:'settle',obligation:detail})}/>} 
    {modal?.type==='account'&&<AccountModal busy={busy} onClose={()=>setModal(null)} onSave={f=>run(()=>createCompleteAccount({organizationId:company.id,...f}),'Conta criada.')} />}
    {modal?.type==='transfer'&&<TransferModal accounts={accounts.filter(x=>x.active&&ymd(x.openingDate)<=localToday())} busy={busy} onClose={()=>setModal(null)} onSave={f=>run(()=>createCompleteTransfer({organizationId:company.id,...f}),'Transferência registrada.')} />}
    {modal?.type==='obligation'&&<ObligationModal direction={modal.direction} entries={linkableEntries.filter(x=>x.type===(modal.direction==='receivable'?'revenue':'expense'))} customers={customers} suppliers={suppliers} categories={categories.filter(x=>x.type===(modal.direction==='receivable'?'revenue':'expense'))} busy={busy} onClose={()=>setModal(null)} onSave={f=>run(()=>createCompleteObligation({organizationId:company.id,direction:modal.direction,...f}),modal.direction==='receivable'?'Conta a receber criada.':'Conta a pagar criada.')} />}
    {modal?.type==='settle'&&<SettlementModal obligation={modal.obligation} accounts={accounts.filter(x=>x.active&&ymd(x.openingDate)<=localToday())} busy={busy} onClose={()=>setModal(null)} onSave={f=>run(()=>settleCompleteObligation({obligationId:modal.obligation.id,...f}),modal.obligation.direction==='receivable'?'Recebimento registrado.':'Pagamento registrado.')} />}
    {modal?.type==='cancel-obligation'&&<ReasonModal title="Cancelar obrigação" text="O histórico de baixas já realizadas será preservado." busy={busy} onClose={()=>setModal(null)} onSave={reason=>run(()=>cancelCompleteObligation({obligationId:modal.obligation.id,reason}),'Obrigação cancelada.')} />}
    {modal?.type==='edit'&&<EditModal obligation={modal.obligation} data={data} busy={busy} onClose={()=>setModal(null)} onSave={f=>run(()=>updateFinanceObligationSafe({obligationId:modal.obligation.id,...f}),'Obrigação atualizada.')} />}
    {modal?.type==='installment'&&<InstallmentModal data={data} company={company} busy={busy} onClose={()=>setModal(null)} onSave={f=>run(()=>createInstallmentPlanV2(f),'Parcelamento criado.')} />}
    {modal?.type==='cancel-plan'&&<ReasonModal title="Cancelar saldo restante" text="Parcelas abertas ou parciais serão canceladas; baixas anteriores permanecem." busy={busy} onClose={()=>setModal(null)} onSave={reason=>run(()=>cancelInstallmentRemainingV2({planId:modal.plan.id,reason}),'Saldo restante cancelado.')} />}
    {modal?.type==='recurring'&&<RecurringModal data={data} company={company} busy={busy} onClose={()=>setModal(null)} onSave={f=>run(()=>createRecurringRuleV2(f),'Recorrência criada.')} />}
    {modal?.type==='stop-recurring'&&<StopRecurringModal busy={busy} onClose={()=>setModal(null)} onSave={(reason,cancelScope)=>run(()=>stopRecurringRuleV3({ruleId:modal.rule.id,reason,cancelScope}),'Recorrência encerrada.')} />}
    {modal?.type==='reverse'&&<ReverseModal target={modal.target} busy={busy} onClose={()=>setModal(null)} onSave={({date,reason})=>run(()=>modal.target.kind==='settlement'?reverseCompleteSettlement({settlementId:modal.target.id,date,reason}):reverseCompleteTransfer({transferId:modal.target.id,date,reason}),modal.target.kind==='settlement'?'Baixa estornada.':'Transferência estornada.')} />}
    {toast&&<div className={styles.toast}>{toast}</div>}
  </div>
}

function HeaderActions({view,onModal}){if(view==='accounts')return <><button className={styles.secondary} onClick={()=>onModal({type:'transfer'})}><Icon name="transfer"/>Transferir</button><button className={styles.primary} onClick={()=>onModal({type:'account'})}><Icon name="plus"/>Nova conta</button></>;if(view==='receivables')return <button className={styles.primary} onClick={()=>onModal({type:'obligation',direction:'receivable'})}><Icon name="plus"/>Nova conta a receber</button>;if(view==='payables')return <button className={styles.primary} onClick={()=>onModal({type:'obligation',direction:'payable'})}><Icon name="plus"/>Nova conta a pagar</button>;if(view==='installments')return <button className={styles.primary} onClick={()=>onModal({type:'installment'})}><Icon name="plus"/>Novo parcelamento</button>;if(view==='recurring')return <button className={styles.primary} onClick={()=>onModal({type:'recurring'})}><Icon name="plus"/>Nova recorrência</button>;return null}

function Overview({accounts,obligations,onView,onDetail}){const open=obligations.filter(x=>['open','partial'].includes(x.status));const overdueRec=open.filter(x=>x.overdue&&x.direction==='receivable');const overduePay=open.filter(x=>x.overdue&&x.direction==='payable');const balance=accounts.filter(x=>x.active).reduce((s,x)=>s+x.balance,0);const rec=open.filter(x=>x.direction==='receivable').reduce((s,x)=>s+x.remaining,0);const pay=open.filter(x=>x.direction==='payable').reduce((s,x)=>s+x.remaining,0);const next=[...open].sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate))).slice(0,7);return <><div className={styles.metrics}><Metric label="Saldo atual" value={money(balance)} detail={`${accounts.filter(x=>x.active).length} contas ativas`}/><Metric label="A receber" value={money(rec)} detail="Saldo em aberto"/><Metric label="A pagar" value={money(pay)} detail="Saldo em aberto"/><Metric label="Receber vencido" value={money(overdueRec.reduce((s,x)=>s+x.remaining,0))} critical={overdueRec.length>0}/><Metric label="Pagar vencido" value={money(overduePay.reduce((s,x)=>s+x.remaining,0))} critical={overduePay.length>0}/></div><div className={styles.grid2}><Panel title="Contas e saldos" action={<button className={styles.link} onClick={()=>onView('accounts')}>Ver contas</button>}>{accounts.length?<div className={styles.accountRows}>{accounts.slice(0,6).map(a=><button key={a.id} onClick={()=>onView('statement')}><span><b>{a.name}</b><small>{kindLabel(a.kind)}{a.institution?` • ${a.institution}`:''}</small></span><strong>{money(a.balance)}</strong></button>)}</div>:<Empty text="Cadastre a primeira conta financeira."/>}</Panel><Panel title="Próximos compromissos" action={<button className={styles.link} onClick={()=>onView('today')}>Abrir Hoje</button>}><ObligationList items={next} onDetail={onDetail}/></Panel></div></>}
function Metric({label,value,detail='',critical=false}){return <article className={`${styles.metric} ${critical?styles.critical:''}`}><small>{label}</small><strong>{value}</strong>{detail&&<span>{detail}</span>}</article>}
function Panel({title,subtitle,action,children}){return <section className={styles.panel}><header><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</header>{children}</section>}
function Empty({text}){return <div className={styles.empty}>{text}</div>}

function Today({accounts,obligations,onDetail}){const today=localToday();const d=new Date(`${today}T12:00:00`);d.setDate(d.getDate()+7);const next7=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const open=obligations.filter(x=>['open','partial'].includes(x.status));const recOver=open.filter(x=>x.direction==='receivable'&&x.dueDate<today),payOver=open.filter(x=>x.direction==='payable'&&x.dueDate<today),due=open.filter(x=>x.dueDate===today),week=open.filter(x=>x.dueDate>today&&x.dueDate<=next7);const balance=accounts.filter(x=>x.active).reduce((s,x)=>s+x.balance,0);const rec7=[...due,...week].filter(x=>x.direction==='receivable').reduce((s,x)=>s+x.remaining,0),pay7=[...due,...week].filter(x=>x.direction==='payable').reduce((s,x)=>s+x.remaining,0);return <><div className={styles.metrics}><Metric label="Saldo atual" value={money(balance)}/><Metric label="A receber vencido" value={money(recOver.reduce((s,x)=>s+x.remaining,0))} critical={recOver.length>0}/><Metric label="A pagar vencido" value={money(payOver.reduce((s,x)=>s+x.remaining,0))} critical={payOver.length>0}/><Metric label="Receber • 7 dias" value={money(rec7)}/><Metric label="Pagar • 7 dias" value={money(pay7)}/></div><div className={styles.grid2}><Panel title="Recebimentos vencidos"><ObligationList items={recOver} onDetail={onDetail}/></Panel><Panel title="Pagamentos vencidos"><ObligationList items={payOver} onDetail={onDetail}/></Panel><Panel title="Vence hoje"><ObligationList items={due} onDetail={onDetail}/></Panel><Panel title="Próximos 7 dias"><ObligationList items={week} onDetail={onDetail}/></Panel></div></>}
function ObligationList({items,onDetail}){if(!items.length)return <Empty text="Nenhum compromisso aqui."/>;return <div className={styles.obligationList}>{[...items].sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate))).map(x=><button key={x.id} onClick={()=>onDetail(x)}><i className={x.direction==='receivable'?styles.inDot:styles.outDot}/><span><b>{x.description}</b><small>{dateBR(x.dueDate)} • {x.direction==='receivable'?'Receber':'Pagar'}</small></span><strong>{money(x.remaining)}</strong></button>)}</div>}

function Accounts({accounts}){return <Panel title="Contas financeiras" subtitle="Saldo inicial mais movimentações efetivamente realizadas.">{accounts.length?<div className={styles.accountGrid}>{accounts.map(a=><article key={a.id}><header><span className={styles.accountIcon}><Icon name="wallet"/></span><em className={a.active?styles.badgeOn:styles.badgeOff}>{a.active?'Ativa':'Inativa'}</em></header><h3>{a.name}</h3><p>{kindLabel(a.kind)}{a.institution?` • ${a.institution}`:''}</p><strong>{money(a.balance)}</strong><footer><span>Inicial {money(a.openingBalance)}</span><span>{dateBR(a.openingDate)}</span></footer></article>)}</div>:<Empty text="Nenhuma conta cadastrada."/>}</Panel>}

function ObligationsView({items,onDetail,onSettle,onCancel}){return <Panel title="Obrigações" subtitle="Competência e caixa permanecem separados.">{items.length?<div className={styles.tableWrap}><table><thead><tr><th>Vencimento</th><th>Descrição</th><th>Status</th><th>Original</th><th>Em aberto</th><th></th></tr></thead><tbody>{[...items].sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate))).map(o=><tr key={o.id}><td>{dateBR(o.dueDate)}</td><td><button className={styles.textButton} onClick={()=>onDetail(o)}>{o.description}</button></td><td><span className={o.overdue?styles.statusLate:styles.status}>{statusLabel(o.displayStatus)}</span></td><td>{money(o.originalAmount)}</td><td><strong>{money(o.remaining)}</strong></td><td><div className={styles.rowActions}>{['open','partial'].includes(o.status)&&<button onClick={()=>onSettle(o)}>{o.direction==='receivable'?'Receber':'Pagar'}</button>}{['open','partial'].includes(o.status)&&<button className={styles.dangerLink} onClick={()=>onCancel(o)}>Cancelar</button>}</div></td></tr>)}</tbody></table></div>:<Empty text="Nenhuma obrigação cadastrada."/>}</Panel>}

function CashFlow({accounts,obligations,movements}){
  const [month,setMonth]=useState(monthNow()),[accountId,setAccountId]=useState('all');
  const today=localToday(),b=monthBounds(month),currentMonth=monthNow(),all=accountId==='all';
  const scope=all?accounts:accounts.filter(a=>a.id===accountId),ids=new Set(scope.map(a=>a.id));
  const actualOpening=scope.reduce((s,a)=>s+(ymd(a.openingDate)<=b.start&&ymd(a.openingDate)<=today?Number(a.openingBalance):0),0)+movements.filter(m=>ids.has(m.accountId)&&ymd(m.date)<b.start&&ymd(m.date)<=today).reduce((s,m)=>s+signed(m.direction,m.amount),0);
  const openingEvents=scope.filter(a=>ymd(a.openingDate)>b.start&&ymd(a.openingDate)<=b.end&&ymd(a.openingDate)<=today).map(a=>({id:`opening-${a.id}`,date:ymd(a.openingDate),label:`Saldo inicial • ${a.name}`,state:'Saldo inicial',effect:Number(a.openingBalance||0),isOpening:true}));
  const realized=movements.filter(m=>ids.has(m.accountId)&&ymd(m.date)>=b.start&&ymd(m.date)<=b.end&&ymd(m.date)<=today&&(all?!isTransferKind(m.kind):true));
  const monthProjected=all?obligations.filter(o=>['open','partial'].includes(o.status)&&ymd(o.dueDate)>=b.start&&ymd(o.dueDate)<=b.end):[];
  const overdueCarry=all&&month===currentMonth?obligations.filter(o=>['open','partial'].includes(o.status)&&ymd(o.dueDate)<b.start):[];
  const futurePrior=all&&month>currentMonth?obligations.filter(o=>['open','partial'].includes(o.status)&&ymd(o.dueDate)<b.start):[];
  const futurePriorNet=futurePrior.reduce((s,o)=>s+(o.direction==='receivable'?o.remaining:-o.remaining),0);
  const accumulationStart=actualOpening+futurePriorNet;
  let running=accumulationStart;
  const rows=[
    ...openingEvents,
    ...realized.map(m=>({id:`m-${m.id}`,date:m.date,label:m.description||'Movimento',state:isTransferKind(m.kind)?'Transferência':'Realizado',effect:signed(m.direction,m.amount)})),
    ...monthProjected.map(o=>({id:`o-${o.id}`,date:o.dueDate,label:o.description,state:'Previsto',effect:o.direction==='receivable'?o.remaining:-o.remaining})),
    ...overdueCarry.map(o=>({id:`overdue-${o.id}`,date:b.start,label:`Vencido • ${o.description}`,state:'Previsto vencido',effect:o.direction==='receivable'?o.remaining:-o.remaining}))
  ].sort((a,c)=>ymd(a.date).localeCompare(ymd(c.date))||Number(Boolean(c.isOpening))-Number(Boolean(a.isOpening))||String(a.id).localeCompare(String(c.id))).map(r=>({...r,balance:(running+=r.effect)}));
  const final=rows.at(-1)?.balance??accumulationStart,min=rows.reduce((m,r)=>Math.min(m,r.balance),accumulationStart);
  return <><div className={styles.filters}><label>Mês<input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label><label>Conta<select value={accountId} onChange={e=>setAccountId(e.target.value)}><option value="all">Todas as contas</option>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label><div><small>Saldo inicial</small><strong>{money(accumulationStart)}</strong></div><div><small>Saldo final projetado</small><strong>{money(final)}</strong></div><div className={min<0?styles.riskBox:''}><small>Menor saldo</small><strong>{money(min)}</strong></div></div>{!all&&<div className={styles.note}>Ao filtrar uma conta, o acumulado mostra somente o realizado. Obrigações futuras ainda não têm conta de liquidação definida.</div>}{all&&month>currentMonth&&futurePrior.length>0&&<div className={styles.note}>O saldo inicial projetado inclui compromissos anteriores ainda em aberto, evitando que meses futuros pareçam mais positivos do que realmente estão.</div>}<div className={styles.tableWrap}><table><thead><tr><th>Data</th><th>Evento</th><th>Estado</th><th>Entrada</th><th>Saída</th><th>Saldo acumulado</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} className={r.balance<0?styles.negativeRow:''}><td>{dateBR(r.date)}</td><td>{r.label}</td><td>{r.state}</td><td className={styles.inText}>{!r.isOpening&&r.effect>0?money(r.effect):'—'}</td><td className={styles.outText}>{!r.isOpening&&r.effect<0?money(Math.abs(r.effect)):'—'}</td><td><strong>{money(r.balance)}</strong></td></tr>)}{!rows.length&&<tr><td colSpan="6"><Empty text="Sem eventos no período."/></td></tr>}</tbody></table></div></>
}

function Statement({accounts,movements}){const [accountId,setAccountId]=useState(accounts[0]?.id||''),[month,setMonth]=useState(monthNow());const today=localToday(),b=monthBounds(month);const a=accounts.find(x=>x.id===accountId);const opening=(a&&ymd(a.openingDate)<=b.start&&ymd(a.openingDate)<=today?Number(a.openingBalance):0)+movements.filter(m=>m.accountId===accountId&&ymd(m.date)<b.start&&ymd(m.date)<=today).reduce((s,m)=>s+signed(m.direction,m.amount),0);const openingRows=a&&ymd(a.openingDate)>b.start&&ymd(a.openingDate)<=b.end&&ymd(a.openingDate)<=today?[{id:`opening-${a.id}`,date:ymd(a.openingDate),description:`Saldo inicial • ${a.name}`,kind:'saldo_inicial',amount:Number(a.openingBalance||0),effect:Number(a.openingBalance||0),isOpening:true,createdAt:''}]:[];let running=opening;const rows=[...openingRows,...movements.filter(m=>m.accountId===accountId&&ymd(m.date)>=b.start&&ymd(m.date)<=b.end&&ymd(m.date)<=today).map(m=>({...m,effect:signed(m.direction,m.amount)}))].sort((x,y)=>ymd(x.date).localeCompare(ymd(y.date))||Number(Boolean(y.isOpening))-Number(Boolean(x.isOpening))||String(x.createdAt||'').localeCompare(String(y.createdAt||''))).map(r=>({...r,running:(running+=r.effect)}));return <><div className={styles.filters}><label>Conta<select value={accountId} onChange={e=>setAccountId(e.target.value)}>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label><label>Mês<input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label><div><small>Saldo inicial</small><strong>{money(opening)}</strong></div></div><div className={styles.tableWrap}><table><thead><tr><th>Data</th><th>Movimento</th><th>Entrada</th><th>Saída</th><th>Saldo</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{dateBR(r.date)}</td><td>{r.description}<small className={styles.subline}>{r.isOpening?'saldo inicial':r.kind}</small></td><td className={styles.inText}>{!r.isOpening&&r.direction==='in'?money(r.amount):'—'}</td><td className={styles.outText}>{!r.isOpening&&r.direction==='out'?money(r.amount):'—'}</td><td><strong>{money(r.running)}</strong></td></tr>)}{!rows.length&&<tr><td colSpan="5"><Empty text="Sem movimentos no período."/></td></tr>}</tbody></table></div></>}

function Installments({data,obligations,companyId,onDetail,onModal}){const plans=data.installmentPlans.filter(x=>x.companyId===companyId);return <div className={styles.cardGrid}>{plans.map(p=>{const members=data.installmentMembers.filter(m=>m.planId===p.id).sort((a,b)=>a.installmentNo-b.installmentNo);const obs=members.map(m=>obligations.find(o=>o.id===m.obligationId)).filter(Boolean);const paid=obs.filter(o=>o.status==='settled').length;const remaining=obs.reduce((s,o)=>s+(o.status==='cancelled'?0:o.remaining),0);return <article className={styles.groupCard} key={p.id}><header><div><small>{p.direction==='receivable'?'A receber':'A pagar'}</small><h3>{p.description}</h3></div><em className={p.status==='active'?styles.badgeOn:styles.badgeOff}>{p.status}</em></header><div className={styles.groupStats}><div><small>Total</small><b>{money(p.totalAmount)}</b></div><div><small>Quitadas</small><b>{paid}/{p.installmentCount}</b></div><div><small>Saldo</small><b>{money(remaining)}</b></div></div><div className={styles.miniRows}>{obs.map((o,i)=><button key={o.id} onClick={()=>onDetail(o)}><span>{i+1}/{p.installmentCount}</span><b>{dateBR(o.dueDate)}</b><strong>{money(o.remaining)}</strong></button>)}</div>{p.status==='active'&&remaining>0&&<footer><button className={styles.dangerLink} onClick={()=>onModal({type:'cancel-plan',plan:p})}>Cancelar saldo restante</button></footer>}</article>})}{!plans.length&&<Empty text="Nenhum parcelamento cadastrado."/>}</div>}

function Recurring({data,obligations,companyId,busy,onDetail,onModal,onRun}){const rules=data.recurringRules.filter(x=>x.companyId===companyId);return <div className={styles.cardGrid}>{rules.map(r=>{const obs=data.recurringMembers.filter(m=>m.recurringId===r.id).map(m=>obligations.find(o=>o.id===m.obligationId)).filter(Boolean).sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate)));return <article className={styles.groupCard} key={r.id}><header><div><small>{r.direction==='receivable'?'Receita recorrente':'Despesa recorrente'}</small><h3>{r.description}</h3></div><em className={r.active?styles.badgeOn:styles.badgeOff}>{r.active?'Ativa':'Encerrada'}</em></header><div className={styles.groupStats}><div><small>Valor</small><b>{money(r.amount)}</b></div><div><small>Dia</small><b>{r.dueDay}</b></div><div><small>Gerada até</small><b>{dateBR(r.generatedThrough)}</b></div></div><div className={styles.miniRows}>{obs.slice(-6).map(o=><button key={o.id} onClick={()=>onDetail(o)}><span>{dateBR(o.dueDate)}</span><b>{statusLabel(o.displayStatus)}</b><strong>{money(o.remaining)}</strong></button>)}</div>{r.active&&<footer><button onClick={()=>onRun(()=>generateRecurringV2({ruleId:r.id,through:monthEndAfter(r.generatedThrough||r.startsOn,6)}),'Mais 6 meses gerados.')} disabled={busy}>Gerar +6 meses</button><button className={styles.dangerLink} onClick={()=>onModal({type:'stop-recurring',rule:r})}>Encerrar</button></footer>}</article>})}{!rules.length&&<Empty text="Nenhuma recorrência cadastrada."/>}</div>}

function History({data,companyId,onReverse}){const [tab,setTab]=useState('settlements');const settlements=data.settlements.filter(x=>x.companyId===companyId).sort((a,b)=>String(b.date).localeCompare(String(a.date)));const transfers=data.transfers.filter(x=>x.companyId===companyId).sort((a,b)=>String(b.date).localeCompare(String(a.date)));return <><div className={styles.tabs}><button className={tab==='settlements'?styles.tabActive:''} onClick={()=>setTab('settlements')}>Baixas</button><button className={tab==='transfers'?styles.tabActive:''} onClick={()=>setTab('transfers')}>Transferências</button></div><div className={styles.tableWrap}>{tab==='settlements'?<table><thead><tr><th>Data</th><th>Obrigação</th><th>Conta</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody>{settlements.map(s=>{const o=data.obligations.find(x=>x.id===s.obligationId);const a=data.accounts.find(x=>x.id===s.accountId);return <tr key={s.id}><td>{dateBR(s.date)}</td><td>{o?.description||'Obrigação'}</td><td>{a?.name||'Conta'}</td><td>{statusLabel(s.status)}</td><td><strong>{money(s.amount)}</strong></td><td>{s.status==='active'&&ymd(s.date)<=localToday()&&<button className={styles.dangerLink} onClick={()=>onReverse({kind:'settlement',id:s.id,date:s.date,label:o?.description||'Baixa'})}>Estornar</button>}</td></tr>})}</tbody></table>:<table><thead><tr><th>Data</th><th>Origem</th><th>Destino</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody>{transfers.map(t=><tr key={t.id}><td>{dateBR(t.date)}</td><td>{data.accounts.find(a=>a.id===t.fromAccountId)?.name||'Conta'}</td><td>{data.accounts.find(a=>a.id===t.toAccountId)?.name||'Conta'}</td><td>{statusLabel(t.status)}</td><td><strong>{money(t.amount)}</strong></td><td>{t.status==='active'&&ymd(t.date)<=localToday()&&<button className={styles.dangerLink} onClick={()=>onReverse({kind:'transfer',id:t.id,date:t.date,label:t.description||'Transferência'})}>Estornar</button>}</td></tr>)}</tbody></table>}</div></>}

function ObligationDrawer({obligation,data,onClose,onEdit,onSettle}){const settlements=data.settlements.filter(x=>x.obligationId===obligation.id).sort((a,b)=>String(b.date).localeCompare(String(a.date)));const revisions=data.revisions.filter(x=>x.obligation_id===obligation.id).sort((a,b)=>String(b.changed_at).localeCompare(String(a.changed_at)));const party=(obligation.direction==='receivable'?data.customers:data.suppliers).find(x=>x.id===(obligation.customerId||obligation.supplierId));const cat=data.categories.find(x=>x.id===obligation.categoryId);return <div className={styles.drawerBackdrop} onMouseDown={e=>e.target===e.currentTarget&&onClose()}><aside className={styles.drawer}><header><div><small>{obligation.direction==='receivable'?'Conta a receber':'Conta a pagar'}</small><h2>{obligation.description}</h2></div><button className={styles.iconButton} onClick={onClose}><Icon name="close"/></button></header><div className={styles.drawerValue}><small>Saldo em aberto</small><strong>{money(obligation.remaining)}</strong><span>Original {money(obligation.originalAmount)} • baixado {money(obligation.settledAmount)}</span></div><dl><div><dt>Vencimento</dt><dd>{dateBR(obligation.dueDate)}</dd></div><div><dt>Status</dt><dd>{statusLabel(obligation.displayStatus)}</dd></div><div><dt>{obligation.direction==='receivable'?'Cliente':'Fornecedor'}</dt><dd>{party?.name||'Não informado'}</dd></div><div><dt>Categoria</dt><dd>{cat?.name||'Sem categoria'}</dd></div><div><dt>Origem</dt><dd>{obligation.origin}</dd></div><div><dt>Observação</dt><dd>{obligation.notes||'—'}</dd></div></dl>{['open','partial'].includes(obligation.status)&&<div className={styles.drawerActions}><button className={styles.secondary} onClick={onEdit}><Icon name="edit"/>Editar</button><button className={styles.primary} onClick={onSettle}>{obligation.direction==='receivable'?'Receber':'Pagar'}</button></div>}<section><h3>Baixas</h3>{settlements.map(s=><div className={styles.auditRow} key={s.id}><span><b>{money(s.amount)}</b><small>{dateBR(s.date)} • {statusLabel(s.status)}</small></span><em>{data.accounts.find(a=>a.id===s.accountId)?.name||'Conta'}</em></div>)}{!settlements.length&&<Empty text="Nenhuma baixa."/>}</section><section><h3>Alterações</h3>{revisions.map(r=><div className={styles.auditRow} key={r.id}><span><b>{r.reason}</b><small>{new Date(r.changed_at).toLocaleString('pt-BR')}</small></span></div>)}{!revisions.length&&<Empty text="Nenhuma edição registrada."/>}</section></aside></div>}

function Modal({title,desc,onClose,children}){return <div className={styles.modalBackdrop} onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className={styles.modal}><header><div><h2>{title}</h2>{desc&&<p>{desc}</p>}</div><button className={styles.iconButton} onClick={onClose}><Icon name="close"/></button></header>{children}</section></div>}
function Field({label,children}){return <label className={styles.field}><span>{label}</span>{children}</label>}
function Actions({busy,onClose,danger=false,label='Salvar'}){return <footer className={styles.actions}><button type="button" onClick={onClose}>Voltar</button><button className={danger?styles.dangerButton:styles.primary} disabled={busy}>{busy?'Salvando…':label}</button></footer>}
function AccountModal({busy,onClose,onSave}){const [f,setF]=useState({name:'',kind:'bank',institution:'',openingBalance:'0',openingDate:localToday()});const p=(k,v)=>setF(x=>({...x,[k]:v}));return <Modal title="Nova conta" desc="Informe o saldo real de partida da conta." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(f)}}><Field label="Nome"><input required value={f.name} onChange={e=>p('name',e.target.value)}/></Field><div className={styles.formGrid}><Field label="Tipo"><select value={f.kind} onChange={e=>p('kind',e.target.value)}><option value="bank">Banco</option><option value="cash">Caixa</option><option value="wallet">Carteira digital</option><option value="other">Outra</option></select></Field><Field label="Instituição"><input value={f.institution} onChange={e=>p('institution',e.target.value)}/></Field></div><div className={styles.formGrid}><Field label="Saldo inicial"><input type="number" step="0.01" value={f.openingBalance} onChange={e=>p('openingBalance',e.target.value)}/></Field><Field label="Data inicial"><input required max={localToday()} type="date" value={f.openingDate} onChange={e=>p('openingDate',e.target.value)}/></Field></div><Actions busy={busy} onClose={onClose}/></form></Modal>}
function TransferModal({accounts,busy,onClose,onSave}){const [f,setF]=useState({fromAccountId:accounts[0]?.id||'',toAccountId:accounts[1]?.id||'',date:localToday(),amount:'',description:''});const p=(k,v)=>setF(x=>({...x,[k]:v}));return <Modal title="Transferir entre contas" desc="Transferências não alteram receita ou despesa da empresa." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(f)}}><div className={styles.formGrid}><Field label="Origem"><select required value={f.fromAccountId} onChange={e=>p('fromAccountId',e.target.value)}>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></Field><Field label="Destino"><select required value={f.toAccountId} onChange={e=>p('toAccountId',e.target.value)}>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></Field></div><div className={styles.formGrid}><Field label="Data"><input required max={localToday()} type="date" value={f.date} onChange={e=>p('date',e.target.value)}/></Field><Field label="Valor"><input required min="0.01" step="0.01" type="number" value={f.amount} onChange={e=>p('amount',e.target.value)}/></Field></div><Field label="Descrição"><input value={f.description} onChange={e=>p('description',e.target.value)}/></Field><Actions busy={busy} onClose={onClose}/></form></Modal>}
function ObligationModal({direction,entries,customers,suppliers,categories,busy,onClose,onSave}){const [f,setF]=useState({origin:'manual',financialEntryId:'',description:'',issueDate:localToday(),dueDate:localToday(),amount:'',customerId:'',supplierId:'',categoryId:'',notes:''});const p=(k,v)=>setF(x=>({...x,[k]:v}));const parties=direction==='receivable'?customers:suppliers;const selected=entries.find(e=>e.id===f.financialEntryId);useEffect(()=>{if(!selected)return;setF(x=>({...x,description:selected.description||x.description,amount:String(selected.allocationRemaining),issueDate:String(selected.date).slice(0,10),customerId:selected.customerId||'',supplierId:selected.supplierId||'',categoryId:selected.categoryId||''}))},[selected?.id]);return <Modal title={direction==='receivable'?'Nova conta a receber':'Nova conta a pagar'} desc="A obrigação controla o financeiro sem somar novamente no resultado." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave({...f,financialEntryId:f.origin==='financial_entry'?f.financialEntryId:null,customerId:direction==='receivable'?f.customerId||null:null,supplierId:direction==='payable'?f.supplierId||null:null,categoryId:f.categoryId||null})}}><Field label="Origem"><select value={f.origin} onChange={e=>p('origin',e.target.value)}><option value="manual">Manual</option><option value="financial_entry">Vincular à competência</option><option value="opening">Saldo de abertura</option></select></Field>{f.origin==='financial_entry'&&<Field label="Lançamento"><select required value={f.financialEntryId} onChange={e=>p('financialEntryId',e.target.value)}><option value="">Selecione</option>{entries.map(e=><option key={e.id} value={e.id}>{e.description} • disponível {money(e.allocationRemaining)}</option>)}</select></Field>}<Field label="Descrição"><input required value={f.description} onChange={e=>p('description',e.target.value)}/></Field><div className={styles.formGrid}><Field label="Emissão"><input type="date" value={f.issueDate} onChange={e=>p('issueDate',e.target.value)}/></Field><Field label="Vencimento"><input required type="date" value={f.dueDate} onChange={e=>p('dueDate',e.target.value)}/></Field></div><div className={styles.formGrid}><Field label="Valor"><input required min="0.01" max={selected?.allocationRemaining||undefined} step="0.01" type="number" value={f.amount} onChange={e=>p('amount',e.target.value)}/></Field><Field label={direction==='receivable'?'Cliente':'Fornecedor'}><select value={direction==='receivable'?f.customerId:f.supplierId} onChange={e=>p(direction==='receivable'?'customerId':'supplierId',e.target.value)}><option value="">Não informado</option>{parties.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field></div><Field label="Categoria"><select value={f.categoryId} onChange={e=>p('categoryId',e.target.value)}><option value="">Sem categoria</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Observação"><textarea rows="2" value={f.notes} onChange={e=>p('notes',e.target.value)}/></Field><Actions busy={busy} onClose={onClose}/></form></Modal>}
function SettlementModal({obligation,accounts,busy,onClose,onSave}){const [f,setF]=useState({accountId:accounts[0]?.id||'',date:localToday(),amount:String(obligation.remaining),notes:''});const p=(k,v)=>setF(x=>({...x,[k]:v}));return <Modal title={obligation.direction==='receivable'?'Registrar recebimento':'Registrar pagamento'} desc={`${obligation.description} • saldo ${money(obligation.remaining)}`} onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(f)}}><Field label="Conta"><select required value={f.accountId} onChange={e=>p('accountId',e.target.value)}>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></Field><div className={styles.formGrid}><Field label="Data"><input required max={localToday()} type="date" value={f.date} onChange={e=>p('date',e.target.value)}/></Field><Field label="Valor"><input required min="0.01" max={obligation.remaining} step="0.01" type="number" value={f.amount} onChange={e=>p('amount',e.target.value)}/></Field></div><Field label="Observação"><textarea rows="2" value={f.notes} onChange={e=>p('notes',e.target.value)}/></Field><Actions busy={busy} onClose={onClose}/></form></Modal>}
function ReasonModal({title,text,busy,onClose,onSave}){const [reason,setReason]=useState('');return <Modal title={title} desc={text} onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(reason)}}><Field label="Motivo"><textarea required rows="4" value={reason} onChange={e=>setReason(e.target.value)}/></Field><Actions busy={busy} onClose={onClose} danger/></form></Modal>}
function EditModal({obligation,data,busy,onClose,onSave}){const [f,setF]=useState({description:obligation.description,issueDate:String(obligation.issueDate||'').slice(0,10),dueDate:String(obligation.dueDate).slice(0,10),amount:String(obligation.originalAmount),customerId:obligation.customerId||'',supplierId:obligation.supplierId||'',categoryId:obligation.categoryId||'',notes:obligation.notes||'',reason:''});const p=(k,v)=>setF(x=>({...x,[k]:v}));const parties=obligation.direction==='receivable'?data.customers:data.suppliers;return <Modal title="Editar obrigação" desc="A alteração será registrada na trilha de auditoria." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave({...f,customerId:f.customerId||null,supplierId:f.supplierId||null,categoryId:f.categoryId||null})}}><Field label="Descrição"><input required value={f.description} onChange={e=>p('description',e.target.value)}/></Field><div className={styles.formGrid}><Field label="Emissão"><input type="date" value={f.issueDate} onChange={e=>p('issueDate',e.target.value)}/></Field><Field label="Vencimento"><input required type="date" value={f.dueDate} onChange={e=>p('dueDate',e.target.value)}/></Field></div><div className={styles.formGrid}><Field label="Valor"><input required min={obligation.settledAmount||.01} step="0.01" type="number" value={f.amount} onChange={e=>p('amount',e.target.value)}/></Field><Field label={obligation.direction==='receivable'?'Cliente':'Fornecedor'}><select value={obligation.direction==='receivable'?f.customerId:f.supplierId} onChange={e=>p(obligation.direction==='receivable'?'customerId':'supplierId',e.target.value)}><option value="">Não informado</option>{parties.filter(x=>x.active&&!x.merged_into).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field></div><Field label="Categoria"><select value={f.categoryId} onChange={e=>p('categoryId',e.target.value)}><option value="">Sem categoria</option>{data.categories.filter(c=>c.active&&c.type===(obligation.direction==='receivable'?'revenue':'expense')).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Observação"><textarea rows="2" value={f.notes} onChange={e=>p('notes',e.target.value)}/></Field><Field label="Motivo da alteração"><textarea required rows="3" value={f.reason} onChange={e=>p('reason',e.target.value)}/></Field><Actions busy={busy} onClose={onClose}/></form></Modal>}
function InstallmentModal({data,company,busy,onClose,onSave}){const [f,setF]=useState({organizationId:company.id,direction:'payable',description:'',totalAmount:'',installmentCount:2,issueDate:localToday(),firstDueDate:localToday(),customerId:'',supplierId:'',categoryId:'',notes:''});const p=(k,v)=>setF(x=>({...x,[k]:v}));const parties=f.direction==='receivable'?data.customers:data.suppliers;return <Modal title="Novo parcelamento" desc="Cada parcela será uma obrigação independente e auditável." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave({...f,customerId:f.direction==='receivable'?f.customerId||null:null,supplierId:f.direction==='payable'?f.supplierId||null:null,categoryId:f.categoryId||null})}}><div className={styles.formGrid}><Field label="Tipo"><select value={f.direction} onChange={e=>p('direction',e.target.value)}><option value="payable">A pagar</option><option value="receivable">A receber</option></select></Field><Field label={f.direction==='receivable'?'Cliente':'Fornecedor'}><select value={f.direction==='receivable'?f.customerId:f.supplierId} onChange={e=>p(f.direction==='receivable'?'customerId':'supplierId',e.target.value)}><option value="">Não informado</option>{parties.filter(x=>x.active&&!x.merged_into).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field></div><Field label="Descrição"><input required value={f.description} onChange={e=>p('description',e.target.value)}/></Field><div className={styles.formGrid}><Field label="Valor total"><input required min="0.01" step="0.01" type="number" value={f.totalAmount} onChange={e=>p('totalAmount',e.target.value)}/></Field><Field label="Parcelas"><input required min="2" max="120" type="number" value={f.installmentCount} onChange={e=>p('installmentCount',e.target.value)}/></Field></div><div className={styles.formGrid}><Field label="Emissão"><input type="date" value={f.issueDate} onChange={e=>p('issueDate',e.target.value)}/></Field><Field label="1º vencimento"><input required type="date" value={f.firstDueDate} onChange={e=>p('firstDueDate',e.target.value)}/></Field></div><Field label="Categoria"><select value={f.categoryId} onChange={e=>p('categoryId',e.target.value)}><option value="">Sem categoria</option>{data.categories.filter(c=>c.active&&c.type===(f.direction==='receivable'?'revenue':'expense')).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Actions busy={busy} onClose={onClose}/></form></Modal>}
function RecurringModal({data,company,busy,onClose,onSave}){const [f,setF]=useState({organizationId:company.id,direction:'payable',description:'',amount:'',dueDay:new Date().getDate(),startsOn:localToday(),endsOn:'',customerId:'',supplierId:'',categoryId:'',notes:'',generateMonths:12});const p=(k,v)=>setF(x=>({...x,[k]:v}));const parties=f.direction==='receivable'?data.customers:data.suppliers;return <Modal title="Nova recorrência" desc="O sistema gera obrigações mensais normais, sem criar uma segunda lógica financeira." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave({...f,endsOn:f.endsOn||null,customerId:f.direction==='receivable'?f.customerId||null:null,supplierId:f.direction==='payable'?f.supplierId||null:null,categoryId:f.categoryId||null})}}><div className={styles.formGrid}><Field label="Tipo"><select value={f.direction} onChange={e=>p('direction',e.target.value)}><option value="payable">Despesa recorrente</option><option value="receivable">Receita recorrente</option></select></Field><Field label={f.direction==='receivable'?'Cliente':'Fornecedor'}><select value={f.direction==='receivable'?f.customerId:f.supplierId} onChange={e=>p(f.direction==='receivable'?'customerId':'supplierId',e.target.value)}><option value="">Não informado</option>{parties.filter(x=>x.active&&!x.merged_into).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field></div><Field label="Descrição"><input required value={f.description} onChange={e=>p('description',e.target.value)}/></Field><div className={styles.formGrid}><Field label="Valor mensal"><input required min="0.01" step="0.01" type="number" value={f.amount} onChange={e=>p('amount',e.target.value)}/></Field><Field label="Dia do vencimento"><input required min="1" max="31" type="number" value={f.dueDay} onChange={e=>p('dueDay',e.target.value)}/></Field></div><div className={styles.formGrid}><Field label="Início"><input required type="date" value={f.startsOn} onChange={e=>p('startsOn',e.target.value)}/></Field><Field label="Fim (opcional)"><input type="date" value={f.endsOn} onChange={e=>p('endsOn',e.target.value)}/></Field></div><Field label="Categoria"><select value={f.categoryId} onChange={e=>p('categoryId',e.target.value)}><option value="">Sem categoria</option>{data.categories.filter(c=>c.active&&c.type===(f.direction==='receivable'?'revenue':'expense')).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Actions busy={busy} onClose={onClose}/></form></Modal>}
function StopRecurringModal({busy,onClose,onSave}){const [reason,setReason]=useState(''),[scope,setScope]=useState('next_month');return <Modal title="Encerrar recorrência" desc="Escolha exatamente o que deve acontecer com obrigações já geradas." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(reason,scope)}}><Field label="Obrigações já geradas"><select value={scope} onChange={e=>setScope(e.target.value)}><option value="keep">Manter todas as obrigações existentes</option><option value="next_month">Cancelar somente a partir do próximo mês</option><option value="all_open">Cancelar abertas a partir de hoje</option></select></Field><div className={styles.note}>{scope==='keep'?'Só impede novas gerações.':scope==='next_month'?'Preserva o mês atual e cancela abertas dos meses seguintes.':'Cancela todas as ocorrências abertas com vencimento a partir de hoje.'}</div><Field label="Motivo"><textarea required rows="4" value={reason} onChange={e=>setReason(e.target.value)}/></Field><Actions busy={busy} onClose={onClose} danger label="Encerrar recorrência"/></form></Modal>}
function ReverseModal({target,busy,onClose,onSave}){const min=ymd(target.date),today=localToday();const initial=min>today?today:today;const [date,setDate]=useState(initial),[reason,setReason]=useState('');const legacyFuture=min>today;return <Modal title={target.kind==='settlement'?'Estornar baixa':'Estornar transferência'} desc={legacyFuture?'Este registro possui data futura legada e precisa ser revisado antes do estorno.':'O original não será apagado; o sistema registra movimento compensatório.'} onClose={onClose}>{legacyFuture?<div className={styles.note}>Não é possível estornar hoje um evento cuja data original está no futuro. Corrija esse registro antes de continuar.</div>:<form onSubmit={e=>{e.preventDefault();onSave({date,reason})}}><Field label="Data do estorno"><input required min={min} max={today} type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="Motivo"><textarea required rows="4" value={reason} onChange={e=>setReason(e.target.value)}/></Field><Actions busy={busy} onClose={onClose} danger label="Confirmar estorno"/></form>}</Modal>}
function Center({text}){return <main className={styles.center}>{text}</main>}
